import{_ as t,o as i,c as s,a3 as a,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const l="/bilder/vorbereitung/schueler-akt-halbj-ankreuzkompetenzen-auswahl.png",u="/bilder/vorbereitung/schueler-akt-halbj-ankreuzkompetenzen.png",g=JSON.parse('{"title":"Ankreuzkompetenzen im Lernabschnitt bewerten","description":"","frontmatter":{"title":"Ankreuzkompetenzen im Lernabschnitt bewerten","source_pageid":1233,"source_revision":4379},"headers":[],"relativePath":"zeugnisse/vorbereitung/kompetenzen-fuer-ankreuzzeugnisse-aktuelles-halbjahr-aktueller-abschnitt.md","filePath":"zeugnisse/vorbereitung/kompetenzen-fuer-ankreuzzeugnisse-aktuelles-halbjahr-aktueller-abschnitt.md"}'),o={name:"zeugnisse/vorbereitung/kompetenzen-fuer-ankreuzzeugnisse-aktuelles-halbjahr-aktueller-abschnitt.md"};function h(d,r,k,c,m,z){return i(),s("div",null,[...r[0]||(r[0]=[a('<h1 id="ankreuzkompetenzen-im-lernabschnitt-bewerten" tabindex="-1">Ankreuzkompetenzen im Lernabschnitt bewerten <a class="header-anchor" href="#ankreuzkompetenzen-im-lernabschnitt-bewerten" aria-label="Permalink to &quot;Ankreuzkompetenzen im Lernabschnitt bewerten&quot;">​</a></h1><p>Bewerten Sie die zuvor zugewiesenen Kompetenzen im aktuellen Lernabschnitt. Voraussetzung sind entsprechend eingerichtete Klassen, Kompetenzen und Fachbelegungen.</p><p><a href="/bilder/vorbereitung/schueler-akt-halbj-ankreuzkompetenzen-auswahl.png"><img src="'+l+'" alt="Wird ein Schüler ausgewählt, für dessen Klasse Ankreuzkompetenzen aktiviert sind, wird der passende Reiter unter Akt. Halbjahr eingeblendet." loading="lazy"></a></p><p><em>Wird ein Schüler ausgewählt, für dessen Klasse Ankreuzkompetenzen aktiviert sind, wird der passende Reiter unter Akt. Halbjahr eingeblendet.</em></p><p>Wird ein Schüler angewählt, für dessen <em>Klasse</em> in <em>Kataloge ➜ Klassen-/Versetzungstabelle</em> der Haken bei <strong>In dieser Klasse werden Ankreuzkompetenzen verwendet</strong> aktiviert ist, wird unter <em>Schüler Akt. Halbjahr</em> der neue Reiter <strong>Kompetenzen für Ankreuzzeugnisse</strong> eingeblendet.</p><p><a href="/bilder/vorbereitung/schueler-akt-halbj-ankreuzkompetenzen.png"><img src="'+u+'" alt="Es werden bei diesem Schüler nun alle Ankreuzkompetenzen aufgeführt, die für ihn hinzugefügt wurden." loading="lazy"></a></p><p><em>Es werden bei diesem Schüler nun alle Ankreuzkompetenzen aufgeführt, die für ihn hinzugefügt wurden.</em></p><p>Es werden im Reiter <em>Schüler ➜ Akt. Halbjahr</em> ➜ <strong>Kompetenzen für Ankreuzzeugnisse</strong> nun fachweise, inklusive der Rubrik <em>Arbeits- und Sozialverhalten</em> und eventuell ein frei definierbares Fach <em>Sonstiges</em> angezeigt.<br> Damit Ankreuzkompetenzen angezeigt werden, müssen</p><ol><li>die Klassen erst - siehe oben - entsprechend markiert sein.</li><li>Ankreuzkompetenzen für die Kombination aus <em>Jahrgang</em> und <em>Fach</em> in <em>Kataloge Angaben für Ankreuzzeugnisse</em> hinterlegt worden sein.</li><li>Der Schüler benötigt die entsprechenden <em>Fächer</em> in den Leistungsdaten. Dies gilt nicht für das ASV, diese können auch ohne Fächer hinzugefügt werden.</li><li>Die Ankreuzkompetenzen müssen für die beabsichtigte Schülergruppe im aktuellen Lernabschnitt über <em>Gruppenprozesse ➜ Noten, Zeugnisvorbereitung</em> ➜ <strong>Ankreuzkompetenzen eintragen</strong> zugewiesen worden sein.</li></ol><p>Dann lassen sich die Kompetenzen wie im Screenshot gezeigt durch Anklicken setzen.</p>',10),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,[n("Wenn das Fenster zu klein ist, ziehen Sie erst ganz oben die Spalte "),e("em",null,"Fach"),n(" breiter. Dann lässt sich die Kompetenzbeschreibung ebenfalls breiter ziehen. Schlussendlich lassen sich dann alle Einträge in der Höhe verändern. SchILD-NRW speichert die hier vorgenommenen Einstellungen.")])],-1),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),n("Tipp")]),e("p",null,[n("Nehmen Sie hier bitte den Artikel "),e("em",null,"Kataloge"),n(),e("strong",null,"Ankreuzkompetenzen"),n(" sowie das Tutorial zu "),e("strong",null,"Grundschulzeugnis Ankreuzzeugnis"),n(" zur Kenntnis.")])],-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Kompetenzen_f%C3%BCr_Ankreuzzeugnisse_((Aktuelles_Halbjahr_/_Aktueller_Abschnitt)",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),n(" · Quellrevision 4379.")],-1)])])}const b=t(o,[["render",h]]);export{g as __pageData,b as default};
